// scripts/build-playground-bundle.js
// Bundles @glyph/core into a single ESM file the playground can `import`.
// Browser target, no Node built-ins.

import { copyFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, "..");

await build({
  entryPoints: [resolve(root, "packages/core/dist/index.js")],
  bundle: true,
  format: "esm",
  target: "es2022",
  platform: "browser",
  outfile: resolve(root, "site/play/glyph-bundle.js"),
  minify: false, // readable — engineers should be able to view-source
  sourcemap: "linked",
  legalComments: "inline",
  banner: {
    js: "// glyph-bundle.js — generated by scripts/build-playground-bundle.js — do not edit",
  },
  // `node:crypto` is unresolvable in a browser bundle; map it to a
  // tiny inline SHA-256 shim that exposes the exact subset
  // render/provenance.ts uses (createHash("sha256").update(s).digest("hex")).
  // The hash output is byte-identical to Node's native createHash — both
  // implement FIPS 180-4 — so the playground's provenance seal is a
  // real cryptographic hash, not a placeholder. Node consumers (CLI,
  // MCP, server renders) still use the native module.
  alias: {
    "node:crypto": resolve(__dirname, "playground-crypto-shim.mjs"),
  },
});

console.log("Wrote site/play/glyph-bundle.js");

// Also copy the published JSON schema next to the bundle so Monaco can
// fetch it at runtime for autocomplete + validation. Keeping it in
// `site/play/` (instead of fetching from packages/) means GH Pages serves
// it with no build step on the visitor's side.
const schemaSrc = resolve(root, "packages/core/dist/spec.schema.json");
const schemaDst = resolve(root, "site/play/spec.schema.json");
await copyFile(schemaSrc, schemaDst);
console.log("Copied spec.schema.json");
